# typed: strict
# frozen_string_literal: true

module Homebrew
  module Bundle
    module CaskDumper
      sig { void }
      def self.reset!
        @casks = nil
        @cask_names = nil
        @cask_oldnames = nil
      end

      sig { returns(T::Array[String]) }
      def self.cask_names
        @cask_names ||= T.let(casks.map(&:to_s), T.nilable(T::Array[String]))
      end

      sig { returns(T::Array[String]) }
      def self.outdated_cask_names
        return [] unless Bundle.cask_inst
